        public static string PlatformIcon(string shortName)
        {
            switch ((shortName ?? "").ToUpperInvariant())
            {
                case "PS1": case "PS2": case "PS3": case "GCN": return "disc";
                case "PSP": return "umd";
                case "VITA": return "handheldwide";
                case "NES": case "SNES": case "N64": case "MD": return "cart";
                case "GBA": return "cartsmall";
                case "NDS": case "3DS": return "handheld";
                case "ARC": return "arcade";
                case "WIN": case "PC": return "monitor";
                case "STEAM": return "windowsgames";
                case "RA": return "trophy";
            }
            return null;
        }
    }
